/*
 * Parasite Eve's own costumes, registered through the `costumes` service exactly as an import pack
 * (another game's) would; it is the example to copy. The creatures are the Collection's
 * (pe_collection/pe_pack_pe1.c). The data is pe_wardrobe_data.h, generated by the bridge
 * (gen_collection_data.py).
 *
 * Keys ("pe1/tshirt", "pe1/melissa") are saved in players' profiles and must never change: a
 * character skin's is "pe1/<folder>", an outfit's comes from its generated name.
 *
 * Costumes: the evening dress (bank 10) and T-shirt (13) are the game's own bundles, with optional
 * room packs (pe_skins/outfit_evening, outfit_tshirt: build_outfit_rooms.py). The long dress
 * (11) and transformed Aya (14) have no full player moveset and are not offered. The character skins
 * (pe_skins/<folder>/, built from the user's disc by the bridge's build_skin.py) are skin
 * bundles the Wardrobe loads (pe_skin_loader.c); one whose folder is missing stays hidden.
 */
#include <ctype.h>
#include <stdio.h>
#include <string.h>

#include "pe_wardrobe.h"
#include "pe_wardrobe_data.h"

#define PE_KEY_MAX 48

static char s_costume_key[PE_SKINS][PE_KEY_MAX];
static PeCostume s_costume[PE_SKINS];

static void pe_slug(char *out, size_t size, const char *name) {
    size_t n = (size_t)snprintf(out, size, "pe1/");
    int gap = 0;
    for (; *name && n + 1 < size; ++name) {
        const unsigned char c = (unsigned char)*name;
        if (isalnum(c)) {
            if (gap && out[n - 1] != '/' && out[n - 1] != '_') out[n++] = '_';
            out[n++] = (char)tolower(c);
            gap = 0;
        } else gap = 1;
    }
    out[n] = 0;
}

static void pe_make_keys(void) {
    static int done;
    int i;
    if (done) return;
    done = 1;
    for (i = 1; i < PE_SKINS; ++i) {                         /* 0 is Aya's own clothes: no costume */
        const PeSkin *k = &g_pe_skins[i];
        if (k->kind == 1) snprintf(s_costume_key[i], PE_KEY_MAX, "pe1/%s", k->folder);
        else pe_slug(s_costume_key[i], PE_KEY_MAX, strncmp(k->name, "Aya: ", 5) == 0 ? k->name + 5 : k->name);
    }
}

const char *pe_pack_pe1_costume_key(int index) {
    pe_make_keys();
    return index > 0 && index < PE_SKINS ? s_costume_key[index] : NULL;
}

static const char *pe_skin_group(const PeSkin *k) {
    return k->price >= 250 ? "Main cast" : k->price >= 100 ? "Supporting cast" : "Extras";
}

void pe_pack_pe1_costumes_register(void) {
    const PeCostumesApi *w = &g_pe_costumes_api;
    int i;
    pe_make_keys();
    for (i = 1; i < PE_SKINS; ++i) {
        const PeSkin *k = &g_pe_skins[i];
        if (k->kind == 0 && k->area != 10 && k->area != 13) continue;   /* no full moveset */
        s_costume[i] = (PeCostume){ s_costume_key[i], k->name, k->kind ? pe_skin_group(k) : "Aya's outfits", k->price,
                                    (int16_t)(k->kind ? -1 : k->area), NULL, NULL,
                                    k->kind ? k->folder : k->area == 10 ? "outfit_evening" : "outfit_tshirt" };
        w->add(&s_costume[i]);
    }
}
